import { createHash } from "node:crypto";
import { canonicalizeJson } from "./canonical-json.js";
import type { AdmissionInput, DecisionArtifactDigests, Sha256Digest } from "./types.js";

export const HASH_DOMAINS = Object.freeze({
  admissionInput: "programmable.autonomous-approval.admission-input.v1",
  components: "programmable.autonomous-approval.component-closure.v1",
  capabilities: "programmable.autonomous-approval.capability-set.v1",
  valueGraph: "programmable.autonomous-approval.value-flow-graph.v1",
  authorityGraph: "programmable.autonomous-approval.authority-graph.v1",
  obligations: "programmable.autonomous-approval.obligation-set.v1",
  conditions: "programmable.autonomous-approval.condition-set.v1",
  disclosures: "programmable.autonomous-approval.disclosure-set.v1",
  blockerWitnesses: "programmable.autonomous-approval.blocker-witness-set.v1",
  decisionReceipt: "programmable.autonomous-approval.decision-receipt.v1",
} as const);

export function canonicalSha256(domain: string, value: unknown): Sha256Digest {
  if (!/^programmable\.[a-z0-9.-]+\.v[1-9][0-9]*$/.test(domain)) {
    throw new TypeError("Hash domain must be a versioned Programmable namespace");
  }
  const hash = createHash("sha256");
  hash.update(domain, "utf8");
  hash.update(Uint8Array.of(0));
  hash.update(canonicalizeJson(value), "utf8");
  return `sha256:${hash.digest("hex")}`;
}

export function digestAdmissionInput(input: AdmissionInput): Sha256Digest {
  return canonicalSha256(HASH_DOMAINS.admissionInput, input);
}

export function digestDecisionArtifacts(input: AdmissionInput): DecisionArtifactDigests {
  return {
    components: canonicalSha256(HASH_DOMAINS.components, input.components),
    capabilities: canonicalSha256(HASH_DOMAINS.capabilities, input.capabilities),
    valueGraph: canonicalSha256(HASH_DOMAINS.valueGraph, input.valueGraph),
    authorityGraph: canonicalSha256(HASH_DOMAINS.authorityGraph, input.authorityGraph),
    obligations: canonicalSha256(HASH_DOMAINS.obligations, input.obligations),
    conditions: canonicalSha256(HASH_DOMAINS.conditions, input.conditions),
    disclosures: canonicalSha256(HASH_DOMAINS.disclosures, input.disclosures),
    blockerWitnesses: canonicalSha256(HASH_DOMAINS.blockerWitnesses, input.blockerWitnesses),
  };
}
