export function assertNestedFactoryPlatformProfileReleaseStatementV1(
  raw: NestedFactoryPlatformProfileReleaseStatementV1,
): Readonly<NestedFactoryPlatformProfileReleaseStatementV1> {
  exactKeys(raw, [
    "applicantAcceptanceVerifierArtifactSha256", "capabilityAdminConfigurationSha256",
    "capabilityCatalogHash", "capabilityHash", "ceremonyPolicySha256", "chainId",
    "deploymentBytesVerificationHash", "deploymentPlanHash", "executionModePolicy", "expectedConfigurationHash",
    "expectedPoolId", "expiresAtEpochSeconds", "independentAuditSha256", "issuedAtEpochSeconds",
    "liveCeremonyRequirement", "manifestHash", "moduleRuntimeBindingHash",
    "permitAuthorityConfigurationSha256",
    "planSchemaId", "portableVerifierArtifactSha256", "predeploymentReceiptHash", "profileId",
    "profileGasAuditSha256", "profileKey", "profileSha256", "profileVersion",
    "releaseAttestationAuthorityBindingHash",
    "releaseId", "releaseRevision", "revenueAttestationSha256", "revenuePolicyHash",
    "revenueVerifierArtifactSha256", "revocationEpoch", "reviewedPlanSha256", "routeId",
    "routeVersion", "routerRuntimeBindingHash", "schemaVersion", "sourceRevisionHash",
    "statementHash",
  ], "nested-factory platform profile release statement");
  if (
    raw.schemaVersion !== "programmable.nested-factory-platform-profile-release-statement.v1"
    || raw.chainId !== "1"
    || raw.routeId !== NESTED_FACTORY_ROUTE_ID_V1
    || raw.routeVersion !== NESTED_FACTORY_ROUTE_VERSION_V1
    || raw.profileId !== EXACT_SHARDS_NESTED_FACTORY_PROFILE_ID_V1
    || raw.profileVersion !== EXACT_SHARDS_NESTED_FACTORY_PROFILE_VERSION_V1
    || raw.profileKey !== EXACT_SHARDS_NESTED_FACTORY_PROFILE_KEY_V1
    || raw.expectedPoolId !== EXACT_SHARDS_POOL_ID_V1
    || raw.expectedConfigurationHash !== EXACT_SHARDS_CONFIGURATION_HASH_V1
    || canonicalizeJson(canonicalExecutionModePolicy(raw.executionModePolicy))
      !== canonicalizeJson(NESTED_FACTORY_EXECUTION_MODE_POLICY_V1)
    || raw.applicantAcceptanceVerifierArtifactSha256
      !== HOOKBUILDER_ACCEPTANCE_PROTOCOL_BINDING_SHA256_V1
    || raw.liveCeremonyRequirement
      !== "fresh-dual-rpc-factory-children-pool-safe-nonce-currentness-before-permit-and-launch"
  ) throw new TypeError("nested-factory platform profile release statement is invalid");
  const issued = BigInt(decimalUint(raw.issuedAtEpochSeconds, 64, "release issue time"));
  const expires = BigInt(decimalUint(raw.expiresAtEpochSeconds, 64, "release expiry"));
  if (
    expires <= issued
    || expires - issued > NESTED_FACTORY_MAXIMUM_PLATFORM_RELEASE_LIFETIME_SECONDS_V1
    || decimalUint(raw.releaseRevision, 64, "release revision") === "0"
  ) throw new TypeError("nested-factory platform profile release validity is invalid");
  decimalUint(raw.revocationEpoch, 64, "release revocation epoch");
  for (const value of [
    raw.capabilityCatalogHash, raw.capabilityHash, raw.profileSha256, raw.reviewedPlanSha256,
    raw.applicantAcceptanceVerifierArtifactSha256, raw.routerRuntimeBindingHash,
    raw.moduleRuntimeBindingHash,
    raw.permitAuthorityConfigurationSha256, raw.capabilityAdminConfigurationSha256,
    raw.deploymentPlanHash, raw.deploymentBytesVerificationHash, raw.predeploymentReceiptHash,
    raw.profileGasAuditSha256, raw.portableVerifierArtifactSha256, raw.ceremonyPolicySha256,
    raw.independentAuditSha256, raw.revenueAttestationSha256,
    raw.revenueVerifierArtifactSha256, raw.releaseAttestationAuthorityBindingHash,
  ]) sha256(value, "nested-factory platform release hash binding");
  for (const value of [
    raw.sourceRevisionHash, raw.manifestHash, raw.revenuePolicyHash,
  ]) nonzeroBytes32(value, "nested-factory platform release EVM hash binding");
  const core = { ...raw } as Record<string, unknown>;
  delete core.statementHash;
  if (raw.statementHash !== canonicalSha256(raw.schemaVersion, core)) {
    throw new TypeError("nested-factory platform profile release statement hash is invalid");
  }
  return deepFreeze(raw);
}

export function nestedFactoryPlatformProfileReleaseSigningBytesV1(
  statement: NestedFactoryPlatformProfileReleaseStatementV1,
): Uint8Array {
  const normalized = assertNestedFactoryPlatformProfileReleaseStatementV1(statement);
  return Buffer.from(`${normalized.schemaVersion}\0${canonicalizeJson(normalized)}`, "utf8");
}

export function createSignedNestedFactoryPlatformProfileReleaseAttestationV1(
  input: Readonly<{
    statement: NestedFactoryPlatformProfileReleaseStatementV1;
    authority: NestedFactoryReleaseAttestationAuthorityV1;
    signatureBase64Url: string;
  }>,
): Readonly<SignedNestedFactoryPlatformProfileReleaseAttestationV1> {
  const statement = assertNestedFactoryPlatformProfileReleaseStatementV1(input.statement);
  const authority = releaseAttestationAuthorityBinding(input.authority);
  if (
    statement.releaseAttestationAuthorityBindingHash
      !== nestedFactoryReleaseAttestationAuthorityBindingHashV1(authority)
  ) throw new TypeError("nested-factory release signature authority is not statement-bound");
  const signature = decodeCanonicalBase64Url(input.signatureBase64Url, "release signature");
  if (signature.byteLength !== 64) throw new TypeError("release Ed25519 signature is not 64 bytes");
  const core = {
    schemaVersion:
      "programmable.signed-nested-factory-platform-profile-release-attestation.v1" as const,
    statement,
    authority,
    signatureBase64Url: input.signatureBase64Url,
    signatureSha256: rawSha256(signature),
  };
  return deepFreeze({
    ...core,
    attestationHash: canonicalSha256(core.schemaVersion, core),
  });
}

export function assertSignedNestedFactoryPlatformProfileReleaseAttestationV1(
  raw: SignedNestedFactoryPlatformProfileReleaseAttestationV1,
): Readonly<SignedNestedFactoryPlatformProfileReleaseAttestationV1> {
  exactKeys(raw, [
    "attestationHash", "authority", "schemaVersion", "signatureBase64Url", "signatureSha256",
    "statement",
  ], "signed nested-factory platform profile release attestation");
  if (raw.schemaVersion
    !== "programmable.signed-nested-factory-platform-profile-release-attestation.v1") {
    throw new TypeError("signed nested-factory platform release schema is invalid");
  }
  const rebuilt = createSignedNestedFactoryPlatformProfileReleaseAttestationV1(raw);
  if (canonicalizeJson(raw) !== canonicalizeJson(rebuilt)) {
    throw new TypeError("signed nested-factory platform release hash is invalid");
  }
  return rebuilt;
}

export function verifySignedNestedFactoryPlatformProfileReleaseAttestationV1(
  input: Readonly<{
    attestation: SignedNestedFactoryPlatformProfileReleaseAttestationV1;
    publicKeyPem: string | Uint8Array;
    expectedRevocationEpoch: string;
    nowEpochSeconds: string;
    catalog: NestedFactoryCapabilityCatalogV1;
    capability: NestedFactoryCapabilityV1;
    predeploymentReceipt: NestedFactoryPredeploymentReceiptV1;
    reviewedPlanSha256: Sha256Digest;
    expectedConfigurationHash: EvmBytes32V1;
  }>,
): Readonly<VerifiedNestedFactoryPlatformProfileReleaseV1> {
  const attestation = assertSignedNestedFactoryPlatformProfileReleaseAttestationV1(
    input.attestation,
  );
  const capability = assertNestedFactoryCapabilityV1(input.capability);
  const activation = capability.activation;
  if (activation === null) {
    throw new NestedFactoryCapabilityError(
      "NESTED_FACTORY_CAPABILITY_DISABLED",
      "nested-factory signed platform release cannot verify before activation",
    );
  }
  if (canonicalizeJson(attestation.authority)
    !== canonicalizeJson(activation.releaseAttestationAuthority)) {
    throw new TypeError("nested-factory platform release used an unbound signature authority");
  }
  const expectedStatement = createNestedFactoryPlatformProfileReleaseStatementV1({
    releaseId: attestation.statement.releaseId,
    releaseRevision: attestation.statement.releaseRevision,
    revocationEpoch: attestation.statement.revocationEpoch,
    issuedAtEpochSeconds: attestation.statement.issuedAtEpochSeconds,
    expiresAtEpochSeconds: attestation.statement.expiresAtEpochSeconds,
    catalog: input.catalog,
    capability,
    predeploymentReceipt: input.predeploymentReceipt,
    reviewedPlanSha256: input.reviewedPlanSha256,
    expectedConfigurationHash: input.expectedConfigurationHash,
  });
  if (canonicalizeJson(attestation.statement) !== canonicalizeJson(expectedStatement)) {
    throw new TypeError("nested-factory signed platform release left the expected artifacts");
  }
  const expectedRevocationEpoch = decimalUint(
    input.expectedRevocationEpoch,
    64,
    "expected platform release revocation epoch",
  );
  const now = BigInt(decimalUint(input.nowEpochSeconds, 64, "platform release current time"));
  if (
    attestation.statement.revocationEpoch !== expectedRevocationEpoch
    || now < BigInt(attestation.statement.issuedAtEpochSeconds)
    || now >= BigInt(attestation.statement.expiresAtEpochSeconds)
  ) throw new TypeError("nested-factory signed platform release is expired or revoked");
  const publicKey = createPublicKey(
    input.publicKeyPem instanceof Uint8Array
      ? Buffer.from(input.publicKeyPem)
      : input.publicKeyPem,
  );
  if (publicKey.asymmetricKeyType !== "ed25519") {
    throw new TypeError("nested-factory release verification key is not Ed25519");
  }
  const spki = publicKey.export({ format: "der", type: "spki" });
  if (rawSha256(Buffer.from(spki)) !== attestation.authority.publicKeySpkiSha256) {
    throw new TypeError("nested-factory release verification key left the capability binding");
  }
  const signature = decodeCanonicalBase64Url(
    attestation.signatureBase64Url,
    "nested-factory platform release signature",
  );
  if (!verifySignature(
    null,
    nestedFactoryPlatformProfileReleaseSigningBytesV1(attestation.statement),
    publicKey,
    signature,
  )) throw new TypeError("nested-factory platform release signature is invalid");
  const core = {
    schemaVersion: "programmable.verified-nested-factory-platform-profile-release.v1" as const,
    attestationHash: attestation.attestationHash,
    statementHash: attestation.statement.statementHash,
    capabilityHash: attestation.statement.capabilityHash,
    releaseRevision: attestation.statement.releaseRevision,
    revocationEpoch: attestation.statement.revocationEpoch,
    verifiedAtEpochSeconds: now.toString(10),
  };
  return deepFreeze({
    ...core,
    verificationHash: canonicalSha256(core.schemaVersion, core),
  });
}

export function assertVerifiedNestedFactoryPlatformProfileReleaseV1(
  raw: VerifiedNestedFactoryPlatformProfileReleaseV1,
): Readonly<VerifiedNestedFactoryPlatformProfileReleaseV1> {
  exactKeys(raw, [
    "attestationHash", "capabilityHash", "releaseRevision", "revocationEpoch", "schemaVersion",
    "statementHash", "verificationHash", "verifiedAtEpochSeconds",
  ], "verified nested-factory platform profile release");
  if (
    raw.schemaVersion !== "programmable.verified-nested-factory-platform-profile-release.v1"
    || decimalUint(raw.releaseRevision, 64, "verified release revision") === "0"
  ) throw new TypeError("verified nested-factory platform profile release is invalid");
  decimalUint(raw.revocationEpoch, 64, "verified release revocation epoch");
  decimalUint(raw.verifiedAtEpochSeconds, 64, "verified release time");
  sha256(raw.attestationHash, "verified release attestation");
  sha256(raw.statementHash, "verified release statement");
  sha256(raw.capabilityHash, "verified release capability");
  const core = { ...raw } as Record<string, unknown>;
  delete core.verificationHash;
  if (raw.verificationHash !== canonicalSha256(raw.schemaVersion, core)) {
    throw new TypeError("verified nested-factory platform release hash is invalid");
  }
  return deepFreeze(raw);
}

export function createNestedFactoryApplicantGrantV1(input: Readonly<{
  issuedAtEpochSeconds: string;
  expiresAtEpochSeconds: string;
  releaseAttestation: SignedNestedFactoryPlatformProfileReleaseAttestationV1;
  releaseVerification: VerifiedNestedFactoryPlatformProfileReleaseV1;
  catalog: NestedFactoryCapabilityCatalogV1;
  capability: NestedFactoryCapabilityV1;
  acceptanceSubject: NestedFactoryApplicantAcceptanceSubjectV1;
  acceptanceHead: NestedFactoryApplicantAcceptanceHeadV1;
  expectedCurrentAcceptanceHash: Sha256Digest;
  launchIdentity: NestedFactoryLaunchIdentityV1;
  compiledRoute: VerifiedNestedFactoryCompiledRouteV1;
}>): Readonly<NestedFactoryApplicantGrantV1> {
  const release = assertSignedNestedFactoryPlatformProfileReleaseAttestationV1(
    input.releaseAttestation,
  );
  const releaseVerification = assertVerifiedNestedFactoryPlatformProfileReleaseV1(
    input.releaseVerification,
  );
  const catalog = assertNestedFactoryCapabilityCatalogV1(input.catalog);
  const capability = assertNestedFactoryCapabilityV1(input.capability);
  const activation = capability.activation;
  if (activation === null) {
    throw new NestedFactoryCapabilityError(
      "NESTED_FACTORY_CAPABILITY_DISABLED",
      "nested-factory applicant grant cannot be created before activation",
    );
  }
  const acceptanceSubject = assertNestedFactoryApplicantAcceptanceSubjectV1(
    input.acceptanceSubject,
  );
  const acceptanceHead = verifyCurrentNestedFactoryApplicantAcceptanceHeadV1({
    subject: acceptanceSubject,
    head: input.acceptanceHead,
    expectedCurrentAcceptanceHash: input.expectedCurrentAcceptanceHash,
    expectedClaimSha256: input.acceptanceHead.claimSha256,
    expectedApplicantAcceptanceRecordHash:
      input.acceptanceHead.applicantAcceptanceRecordHash,
  });
  const identity = assertNestedFactoryLaunchIdentityV1(input.launchIdentity);
  const compiledRoute = assertVerifiedNestedFactoryCompiledRouteV1(input.compiledRoute);
  const resolved = resolveEnabledNestedFactoryCapabilityV1({
    catalog,
    profileId: capability.profile.profileId,
    profileVersion: capability.profile.profileVersion,
    routePayloadHash: compiledRoute.routePayloadHash,
    expectedResultHash: compiledRoute.expectedResultHash,
  });
  if (
    releaseVerification.attestationHash !== release.attestationHash
    || releaseVerification.statementHash !== release.statement.statementHash
    || releaseVerification.capabilityHash !== capability.capabilityHash
    || release.statement.capabilityHash !== capability.capabilityHash
    || resolved.capabilityHash !== capability.capabilityHash
    || compiledRoute.capabilityHash !== capability.capabilityHash
    || compiledRoute.routePayloadHash !== identity.routePayloadHash
    || identity.launchWallet !== address(EXACT_SHARDS_LAUNCH_WALLET_V1, "Shards launch wallet")
  ) throw new TypeError("nested-factory applicant grant left the verified release or launch");
  const issuedAtEpochSeconds = decimalUint(
    input.issuedAtEpochSeconds,
    64,
    "nested-factory applicant grant issue time",
  );
  const expiresAtEpochSeconds = decimalUint(
    input.expiresAtEpochSeconds,
    64,
    "nested-factory applicant grant expiry",
  );
  if (
    BigInt(issuedAtEpochSeconds) < BigInt(releaseVerification.verifiedAtEpochSeconds)
    || BigInt(expiresAtEpochSeconds) <= BigInt(issuedAtEpochSeconds)
    || BigInt(expiresAtEpochSeconds) > BigInt(release.statement.expiresAtEpochSeconds)
  ) throw new TypeError("nested-factory applicant grant validity is outside the release");
  const core = {
    schemaVersion: "programmable.nested-factory-applicant-grant.v1" as const,
    chainId: "1" as const,
    issuedAtEpochSeconds,
    expiresAtEpochSeconds,
    releaseAttestationHash: release.attestationHash,
    releaseVerificationHash: releaseVerification.verificationHash,
    releaseStatementHash: release.statement.statementHash,
    capabilityHash: capability.capabilityHash,
    acceptanceSubjectHash: acceptanceSubject.acceptanceSubjectHash,
    currentAcceptanceHash: acceptanceHead.acceptanceHash,
    applicantAcceptanceClaimSha256: acceptanceHead.claimSha256,
    applicantAcceptanceRecordHash: acceptanceHead.applicantAcceptanceRecordHash,
    launchIdentityHash: identity.identityHash,
    launchId: identity.launchId,
    launchWallet: identity.launchWallet,
    permitNonce: identity.permitNonce,
    routePayloadHash: compiledRoute.routePayloadHash,
    expectedResultHash: compiledRoute.expectedResultHash,
    compiledRouteVerificationHash: compiledRoute.verificationHash,
    revenuePolicyHash: capability.revenuePolicyHash,
    expectedPoolId: release.statement.expectedPoolId,
    expectedConfigurationHash: release.statement.expectedConfigurationHash,
    applicantActionSelector: activation.routerDirectLaunchSelector,
    executionModePolicy: activation.executionModePolicy,
  };
  return deepFreeze({
    ...core,
    grantHash: canonicalSha256(core.schemaVersion, core),
  });
}

